replacements.after:
[data-preview="v3"] .preview-comparison { margin-block:28px; }
[data-preview="v3"] .preview-comparison-key { display:flex; flex-wrap:wrap; gap:12px 28px; margin-bottom:24px; font-family:var(--ff-body); font-size:1rem; }
[data-preview="v3"] .preview-comparison article { border-top:1px solid currentColor; border-color:color-mix(in srgb,currentColor 22%,transparent); padding-block:22px; }
[data-preview="v3"] .preview-comparison article :is(p,h3) { display:grid; grid-template-columns:20px minmax(0,1fr); gap:12px; margin:0; }
[data-preview="v3"] .preview-comparison article h3 { margin-top:12px; font-size:clamp(1.3rem,2vw,1.75rem); line-height:1.35; }
[data-preview="v3"] .preview-comparison article p { font-size:1rem; line-height:1.6; }
[data-preview="v3"] .preview-wants { list-style:none; margin:20px 0 28px; padding:0; }
[data-preview="v3"] .preview-wants li { display:grid; grid-template-columns:24px minmax(0,1fr); gap:16px; padding-block:16px; border-bottom:1px solid color-mix(in srgb,currentColor 20%,transparent); }
[data-preview="v3"] .preview-wants li > span { opacity:.6; font-size:.75rem; padding-top:8px; }
[data-preview="v3"] .preview-wants li p { margin:0; font-size:clamp(1.2rem,2vw,1.6rem); line-height:1.4; }
[data-preview="v3"] .preview-benefits { position:relative; margin:48px auto 64px; padding:0; width:min(calc(100% - 80px),1200px); }
[data-preview="v3"] .preview-benefits-pin { padding-block:24px; }
[data-preview="v3"] .preview-benefits[data-pinned="true"] .preview-benefits-pin { position:sticky; top:24px; }
[data-preview="v3"] .preview-benefits h2 { font-family:var(--ff-display); font-weight:400; font-size:clamp(1.8rem,3vw,3rem); line-height:1.15; margin:0 0 28px; }
[data-preview="v3"] .preview-benefits-window { overflow:clip; }
[data-preview="v3"] .preview-benefits-track { display:grid; gap:20px; }
[data-preview="v3"] .preview-benefits[data-pinned="true"] .preview-benefits-track { display:flex; }
[data-preview="v3"] .preview-benefits article { flex:0 0 min(380px,85%); padding:24px; border:1px solid color-mix(in srgb,currentColor 24%,transparent); border-radius:12px; box-sizing:border-box; }
[data-preview="v3"] .preview-benefit-number { opacity:.6; font-size:.8rem; }
[data-preview="v3"] .preview-benefits article h3 { font-family:var(--ff-display); font-weight:400; font-size:1.7rem; line-height:1.25; margin:14px 0; }
[data-preview="v3"] .preview-benefits article p { margin:0; font-size:1rem; font-weight:400; line-height:1.6; }
[data-preview="v3"] .preview-benefits-close { font-size:1rem; line-height:1.5; max-width:720px; margin:24px 0 0; }
[data-preview="v3"] .preview-cta-note { display:block; font-family:var(--ff-body); font-size:.78rem; font-weight:400; letter-spacing:0; text-transform:none; line-height:1.4; margin-top:6px; }
[data-preview="v3"] .preview-cotton { background-color:var(--ink,#1c1c1a); background-image:var(--tex-cotton); background-size:768px 768px; }
[data-preview="v3"] .preview-smile { background:none; }
[data-preview="v3"] .preview-education-list { display:grid; gap:24px; }
[data-preview="v3"] .preview-education-list li { margin:0!important; }
[data-preview="v3"] .proof-item .preview-education-list strong { font-family:var(--ff-body); font-size:1rem; line-height:1.5; font-weight:600; letter-spacing:0; text-transform:none; }
[data-preview="v3"] .proof-item .preview-education-list { margin-top:18px!important; }
[data-preview="v3"] .secondary-illustrated--needs { display:block; }
[data-preview="v3"] .preview-work-intro .m-eyebrow { margin-bottom:18px; }
[data-preview="v3"] .preview-work-intro > p:not(.m-eyebrow):not(.small) { font-size:1.3rem; line-height:1.5; max-width:42ch; }
[data-preview="v3"] .preview-work-intro > .m-text-link { display:flex; width:fit-content; margin-top:28px; }
@media (max-width:899px) {
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-audience-orbit { display:grid; grid-template-columns:1fr; min-height:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-audience-orbit .m-salto { position:relative; inset:auto; grid-area:auto; width:min(100%,460px); margin:12px auto 24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-audience-copy { position:relative; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-missing { margin-top:32px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-missing h3 { margin-bottom:14px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-work-layout { display:grid; grid-template-columns:90px minmax(0,1fr); gap:24px; align-items:center; max-width:none; padding:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-handstand-composition { position:relative; top:auto; width:90px; height:242px; min-height:0; margin:0; grid-column:1; grid-row:1; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .m-handstand { width:90px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-work-text { display:contents; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-work-text h2 { text-align:left; grid-column:2; grid-row:1; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-work .preview-comparison { grid-column:1/-1; width:100%; max-width:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-benefits { width:calc(100% - 2 * var(--m-gutter)); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-needs-opening { display:block; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-needs-opening p + p { margin-top:28px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-between .m-editorial-stack article { padding-block:22px; border-top:1px solid var(--m-rule); }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-cotton { background-color:#1c1c1a; background-image:var(--tex-cotton); background-size:768px 768px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-proof { display:flex; flex-direction:column; gap:32px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-proof-education { width:100%; order:2; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-proof-numbers { display:flex; width:100%; gap:48px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-about-composition { grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:24px; align-items:start; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading { contain:none; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-about-aside { margin-top:20px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-about-aside p { font-size:.95rem; line-height:1.6; margin-top:16px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-bio { font-size:1rem; line-height:1.7; margin-top:28px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] :is(.m-home-about,.m-boundaries) .m-text-link { display:flex; width:fit-content; margin-top:24px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-hero--collaboration .preview-smile img { object-fit:contain; object-position:center bottom; }
}
@media (max-width:479px) {
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-about-composition { grid-template-columns:1fr; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading { display:grid; grid-template-columns:1fr auto; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading .m-eyebrow { grid-area:1/1; align-self:end; margin:0 0 8px; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading h2 { grid-area:2/1; align-self:start; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .m-home-about .m-about-heading .m-about-symbol { grid-column:2; grid-row:1/3; margin:0; }
 .tm-mobile[data-mobile-version][data-preview="v3"] .preview-about-aside { grid-column:1/-1; grid-row:3; }
}
@media (prefers-reduced-motion:reduce) {
 [data-preview="v3"] .preview-benefits { height:auto!important; }
 [data-preview="v3"] .preview-benefits .preview-benefits-pin { position:static; }
 [data-preview="v3"] .preview-benefits .preview-benefits-track { display:grid; transform:none!important; }
}
